return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/correlation-id-required.md"),
              new JProperty("title", "Correlation Id Required"),
              new JProperty("status", 400),
              new JProperty("detail", "Every call must carry a Correlation-Id header, for example ord-4711."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }

send-one-way-request.set-body:
@{
        var token = context.Variables.GetValueOrDefault<Jwt>("agentToken");
        var agentId = token?.Claims.GetValueOrDefault("appid", token?.Claims.GetValueOrDefault("azp", "")) ?? "";
        var body = context.Request.Body?.As<string>(preserveContent: true) ?? "";
        var truncated = body.Length > 16000;
        var e = new JObject(
          new JProperty("specversion", "1.0"),
          new JProperty("id", context.RequestId.ToString()),
          new JProperty("source", "/apim-intplat-agents/" + context.Api.Id),
          new JProperty("type", "com.acme.platform.agent.action"),
          new JProperty("time", DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ss.fffZ")),
          new JProperty("datacontenttype", "application/json"),
          new JProperty("correlationid", context.Request.Headers.GetValueOrDefault("Correlation-Id", "")),
          new JProperty("componentid", context.Api.Id));
        foreach (var key in new[] { "orderId", "customerId" }) {
          var value = context.Request.MatchedParameters.GetValueOrDefault(key, context.Request.Url.Query.GetValueOrDefault(key, ""));
          if (!string.IsNullOrEmpty(value)) { e.Add(key.ToLowerInvariant(), value); }
        }
        e.Add("data", new JObject(
          new JProperty("gateway", "apim-intplat-agents"),
          new JProperty("agentId", agentId),
          new JProperty("method", context.Request.Method),
          new JProperty("path", context.Request.OriginalUrl.Path),
          new JProperty("query", context.Request.OriginalUrl.QueryString),
          new JProperty("operationId", context.Operation?.Id ?? ""),
          new JProperty("subscription", context.Subscription?.Name ?? ""),
          new JProperty("requestBody", truncated ? body.Substring(0, 16000) : body),
          new JProperty("requestBodyTruncated", truncated)));
        return e.ToString();
      }

return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/agent-token-required.md"),
              new JProperty("title", "Agent Token Required"),
              new JProperty("status", 401),
              new JProperty("detail", "Agents call this gateway with an Entra ID token for the intplat-agent-gateway application and the Agent.Act role."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }
